B.a24=new A.f4("WHERE IN (Subquery)","Filter rows matching values from an inner query","WHERE column_name IN (\n  SELECT column_name\n  FROM sub_table\n  WHERE sub_condition\n)","Filtering")
B.a20=new A.f4("WHERE NOT IN (Subquery)","Exclude rows matching values from an inner query","WHERE column_name NOT IN (\n  SELECT column_name\n  FROM sub_table\n  WHERE sub_condition\n)","Filtering")
B.a21=new A.f4("WHERE EXISTS (Subquery)","Check for the existence of rows in a correlated subquery","WHERE EXISTS (\n  SELECT 1\n  FROM sub_table st\n  WHERE st.foreign_id = main_table.id\n)","Filtering")
B.a1Z=new A.f4("WHERE NOT EXISTS (Subquery)","Filter for records that have no matching records in another table","WHERE NOT EXISTS (\n  SELECT 1\n  FROM sub_table st\n  WHERE st.foreign_id = main_table.id\n)","Filtering")
B.a25=new A.f4("WITH CTE (Common Table Expression)","Define a temporary named result set to simplify complex queries","WITH cte_summary AS (\n  SELECT \n    category_id,\n    COUNT(*) AS total_items,\n    AVG(price) AS avg_price\n  FROM items\n  GROUP BY category_id\n)\nSELECT \n  c.category_name,\n  s.total_items,\n  s.avg_price\nFROM categories c\nJOIN cte_summary s ON c.id = s.category_id;","CTE / Modular")
B.a27=new A.f4("Multiple CTEs (Chained WITH)","Chain multiple Common Table Expressions together","WITH raw_data AS (\n  SELECT * FROM orders WHERE status = :status\n),\naggregated AS (\n  SELECT user_id, SUM(total) AS spend FROM raw_data GROUP BY user_id\n)\nSELECT u.username, a.spend\nFROM users u\nJOIN aggregated a ON u.id = a.user_id\nORDER BY a.spend DESC;","CTE / Modular")
B.a26=new A.f4("Scalar Subquery in SELECT","Fetch a single calculated value for each row","SELECT \n  t.id,\n  t.name,\n  (\n    SELECT COUNT(*)\n    FROM related_items r\n    WHERE r.parent_id = t.id\n  ) AS item_count\nFROM parent_table t;","Projection")
B.a23=new A.f4("Derived Table in FROM / JOIN","Join with a subquery as a virtual table","JOIN (\n  SELECT user_id, MAX(created_at) AS latest_activity\n  FROM activity_logs\n  GROUP BY user_id\n) latest ON latest.user_id = u.id","Joins")
B.a22=new A.f4("Window Function OVER (PARTITION BY)","Perform analytical calculations across rows related to the current row","COUNT(*) OVER (PARTITION BY category_id) AS items_in_category","Analytics")
B.a2_=new A.f4("Conditional CASE WHEN Expression","Multi-branch conditional logic inside SELECT or WHERE","CASE \n  WHEN status = 1 THEN 'Active'\n  WHEN status = 2 THEN 'Pending'\n  ELSE 'Inactive'\nEND AS status_label","Expressions")
